// Tester Loop — review code_review queue every 30 min
// Sends FULL issue data so Tester can act without needing to query
const SK = $env.SUPABASE_SERVICE_ROLE_KEY;
const SUPA = '${NEXT_PUBLIC_SUPABASE_URL}';
const h = { apikey: SK, Authorization: 'Bearer ' + SK };
const TRIGGER_URL = 'http://127.0.0.1:8787/trigger-agent';
const MC_API = 'http://localhost:3000/api/issues';

// Only pick up 1 issue at a time (one-at-a-time lane)
const issues = await helpers.httpRequest({
  method: 'GET',
  url: SUPA + '/rest/v1/issues?assignee=eq.tester&status=eq.code_review&tester_status=eq.pending&select=id,task_key,title,description,acceptance_criteria,implementation_notes,commit_sha,feature_branch,pr_url,type,project,severity&limit=1&order=created_at.asc',
  headers: h
});
if (!Array.isArray(issues) || !issues.length) return [{ json: { action: 'idle', queue: 0 } }];

const issue = issues[0];
const prompt = [
  'You are Tester. One issue is assigned to you in code_review. Review it now.',
  '',
  '## Issue: ' + issue.task_key + ' — ' + issue.title,
  'Type: ' + issue.type + ' | Project: ' + issue.project + ' | Severity: ' + (issue.severity || 'not set'),
  'tier: P1 (default),
  '',
  '## Acceptance Criteria',
  issue.acceptance_criteria || '(not set — review description instead)',
  '',
  '## Implementation Notes (what was built)',
  issue.implementation_notes || '(not set)',
  '',
  '## References',
  'commit_sha: ' + (issue.commit_sha || 'none'),
  'feature_branch: ' + (issue.feature_branch || 'none'),
  'pr_url: ' + (issue.pr_url || 'none'),
  '',
  '## Your Task',
  'Review the implementation against the acceptance criteria.',
  'If P2/P3 tier: auto-pass.',
  'If P1/P0 or unset: verify each AC item.',
  '',
  'PASS: PATCH http://localhost:3000/api/issues with:',
  '  { "id": "' + issue.id + '", "tester_status": "passed", "tester_notes": "<summary>", "transitioned_by": "tester" }',
  '',
  'FAIL: PATCH with:',  
  '  { "id": "' + issue.id + '", "tester_status": "failed", "tester_notes": "<what failed and why>", "transitioned_by": "tester" }',
  '',
  'Supabase service role key for any direct queries: ' + SK,
  'Supabase URL: ' + SUPA,
].join('\n');

try {
  await helpers.httpRequest({
    method: 'POST', url: TRIGGER_URL,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ agentId: 'tester', message: prompt })
  });
  return [{ json: { action: 'tester_triggered', task: issue.task_key, tier: issue.test_tier } }];
} catch(e) {
  return [{ json: { action: 'error', message: e.message } }];
}
